+    // column's menu or the cell's content, and the menu shown is the one in place now.
+    auto const candidate = ResolveContextFlyout(target);
+    if (!candidate)
+    {
+        return false;
+    }
+
+    ShowContextFlyout(target, candidate, args);
+    return true;
